package dev.rodrigosambade.chat;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;
public final class ChatServer implements AutoCloseable{private final ServerSocket server;private final ExecutorService workers=Executors.newCachedThreadPool();private final NickRegistry<ClientSession>registry=new NickRegistry<>();private volatile boolean running=true;public ChatServer(int port)throws IOException{server=new ServerSocket(port);}public int port(){return server.getLocalPort();}public void serve()throws IOException{while(running){try{Socket s=server.accept();workers.submit(()->handle(s));}catch(SocketException e){if(running)throw e;}}}private void handle(Socket socket){ClientSession session=null;String nick=null;try(socket){var in=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.UTF_8));var out=new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(),StandardCharsets.UTF_8));String hello=in.readLine();if(hello==null||!hello.startsWith("NICK ")){send(out,"ERROR expected NICK");return;}nick=hello.substring(5).trim();session=new ClientSession(out);if(!registry.register(nick,session)){send(out,"ERROR duplicate nick");return;}send(out,"OK");broadcast("JOIN "+nick);broadcastUsers();for(String line;(line=in.readLine())!=null;){if(line.equals("QUIT"))break;if(line.startsWith("MSG "))broadcast("MESSAGE "+nick+" "+line.substring(4));else send(out,"ERROR expected MSG or QUIT");}}catch(IOException ignored){}finally{if(nick!=null&&session!=null){registry.remove(nick,session);broadcast("LEAVE "+nick);broadcastUsers();}}}private void broadcastUsers(){broadcast("USERS "+String.join(",",registry.nicks()));}private void broadcast(String m){for(ClientSession c:registry.values())c.send(m);}private static void send(BufferedWriter out,String m)throws IOException{out.write(m);out.newLine();out.flush();}private static final class ClientSession{private final BufferedWriter out;ClientSession(BufferedWriter out){this.out=out;}synchronized void send(String m){try{ChatServer.send(out,m);}catch(IOException ignored){}}}@Override public void close()throws IOException{running=false;server.close();workers.shutdownNow();}public static void main(String[]a)throws Exception{int p=a.length>0?Integer.parseInt(a[0]):5000;try(var s=new ChatServer(p)){System.out.println("Chat en puerto "+s.port());s.serve();}}}
